import os

from juno import config
from juno.adapters import cardwrite, fs, store
from juno.adapters.vaultview import RETIRED_FILE, DiskVault
from juno.core import packs

LEARNED_REL = "_generated/learned.md"
HEADER = (
    "# Learned\n\nGenerated by Juno from the Learned: lines of handoff cards; rebuilt when a "
    "handoff file changes. Do not edit.\n\n"
)


def handoff_files(cfg: config.Config) -> list[str]:
    directory = os.path.join(cfg.vault, "handoffs")
    try:
        names = os.listdir(directory)
    except OSError:
        return []
    return [os.path.join(directory, n) for n in sorted(names) if n.endswith(".md")]


def stale(cfg: config.Config) -> bool:
    files = handoff_files(cfg)
    if not files:
        return False
    try:
        built = os.stat(os.path.join(cfg.vault, *LEARNED_REL.split("/"))).st_mtime
    except OSError:
        return True
    marker = os.path.join(cfg.state, RETIRED_FILE)
    if os.path.exists(marker):
        files.append(marker)
    try:
        return any(os.stat(f).st_mtime > built for f in files)
    except OSError:
        return True


def entries(cfg: config.Config) -> list[str]:
    found = []
    for card in packs.all_cards(DiskVault(cfg)):
        sentence = str(card.get("learned") or "").strip()
        if sentence and sentence.lower().rstrip(".") != "none":
            found.append(f"- {str(card['time'])[:10]} · {sentence} · {card['path']}")
    return found


def built(cfg: config.Config) -> bool:
    return os.path.exists(os.path.join(cfg.vault, *LEARNED_REL.split("/")))


def rebuild(cfg: config.Config, timeout: float = 2.0) -> int:
    try:
        with cardwrite.vault_lock(cfg, timeout):
            lines = entries(cfg)
            target = os.path.join(cfg.vault, *LEARNED_REL.split("/"))
            os.makedirs(os.path.dirname(target), exist_ok=True)
            fs.atomic_write(target, (HEADER + "\n".join(lines)).rstrip("\n").encode() + b"\n")
            return len(lines)
    except TimeoutError as exc:
        store.log_error(cfg, "learned", exc)
        return -1
